BEGIN;
ALTER TABLE public.players ADD COLUMN IF NOT EXISTS display_name_mode text NOT NULL DEFAULT 'preferred';
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='players_display_name_mode_check') THEN ALTER TABLE public.players ADD CONSTRAINT players_display_name_mode_check CHECK (display_name_mode IN ('legal','preferred')); END IF; END $$;
CREATE INDEX IF NOT EXISTS idx_players_profile_visibility ON public.players(profile_visibility);
CREATE SEQUENCE IF NOT EXISTS public.playpro_passport_user_no_seq AS bigint START WITH 1 INCREMENT BY 1 MINVALUE 1 NO MAXVALUE CACHE 1;
CREATE TABLE IF NOT EXISTS public.identity_verifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),profile_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,subject_type text NOT NULL CHECK(subject_type IN ('player','coach','club_owner','organizer','referee')),id_type text NOT NULL CHECK(id_type IN ('mykad','mykid','passport')),legal_name_claimed text NOT NULL,birth_state_code text,masked_identifier text,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','verified','rejected','cancelled')),reviewer_profile_id uuid REFERENCES public.profiles(id),reviewer_note text,provider_reference text,submitted_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_identity_verifications_profile ON public.identity_verifications(profile_id,subject_type,status);
CREATE UNIQUE INDEX IF NOT EXISTS ux_identity_verifications_pending ON public.identity_verifications(profile_id,subject_type) WHERE status='pending';
ALTER TABLE public.identity_verifications ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "identity verification owner read" ON public.identity_verifications;
CREATE POLICY "identity verification owner read" ON public.identity_verifications FOR SELECT TO authenticated USING(profile_id=(SELECT auth.uid()));
REVOKE ALL ON public.identity_verifications FROM anon; GRANT SELECT,INSERT ON public.identity_verifications TO authenticated;
CREATE OR REPLACE FUNCTION public.request_player_kyc(p_id_type text,p_legal_name text,p_birth_state_code text DEFAULT NULL,p_masked_identifier text DEFAULT NULL,p_provider_reference text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE v_uid uuid=(SELECT auth.uid());v_player public.players%ROWTYPE;v_id uuid; BEGIN IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF; SELECT * INTO v_player FROM public.players WHERE profile_id=v_uid AND is_active=true LIMIT 1; IF NOT FOUND THEN RAISE EXCEPTION 'Player profile not found' USING ERRCODE='P0002'; END IF; IF lower(trim(coalesce(p_id_type,''))) NOT IN('mykad','mykid','passport') THEN RAISE EXCEPTION 'KYC mesti menggunakan MyKad, MyKid atau Passport' USING ERRCODE='22023'; END IF; IF nullif(trim(coalesce(p_legal_name,'')),'') IS NULL THEN RAISE EXCEPTION 'Nama sah diperlukan untuk KYC' USING ERRCODE='22023'; END IF; IF v_player.verification_status='verified' THEN RETURN jsonb_build_object('ok',true,'status','verified','player_id',v_player.id,'football_passport_no',v_player.football_passport_no); END IF; INSERT INTO public.identity_verifications(profile_id,subject_type,id_type,legal_name_claimed,birth_state_code,masked_identifier,provider_reference) VALUES(v_uid,'player',lower(trim(p_id_type)),trim(p_legal_name),nullif(trim(p_birth_state_code),''),nullif(trim(p_masked_identifier),''),nullif(trim(p_provider_reference),'')) ON CONFLICT DO NOTHING RETURNING id INTO v_id; RETURN jsonb_build_object('ok',true,'status','pending','kyc_id',v_id,'player_id',v_player.id); END; $$;
REVOKE ALL ON FUNCTION public.request_player_kyc(text,text,text,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.request_player_kyc(text,text,text,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.update_my_player_profile(p_payload JSONB) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE v_uid uuid=(SELECT auth.uid());v_player public.players%ROWTYPE;v_position_code text;v_position public.player_position;v_name text;v_display text; BEGIN IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF; SELECT * INTO v_player FROM public.players WHERE profile_id=v_uid LIMIT 1; IF NOT FOUND THEN RAISE EXCEPTION 'Player profile not found'; END IF; v_position_code=lower(trim(coalesce(p_payload->>'position',''))); IF v_position_code<>'' THEN v_position=CASE WHEN v_position_code IN('gk','goalkeeper') THEN 'goalkeeper'::public.player_position WHEN v_position_code IN('cb','lb','rb','lwb','rwb','defender') THEN 'defender'::public.player_position WHEN v_position_code IN('dm','cm','am','lm','rm','midfielder') THEN 'midfielder'::public.player_position WHEN v_position_code IN('cf','st','ss','forward') THEN 'forward'::public.player_position ELSE NULL END; IF v_position IS NULL THEN RAISE EXCEPTION 'Invalid position' USING ERRCODE='22023'; END IF; END IF; IF p_payload ? 'full_name' THEN v_name=nullif(trim(p_payload->>'full_name'),''); IF v_player.verification_status='verified' AND v_name IS DISTINCT FROM v_player.full_name THEN RAISE EXCEPTION 'Nama sah dikunci selepas KYC disahkan' USING ERRCODE='42501'; END IF; END IF; v_display=lower(trim(coalesce(p_payload->>'display_name_mode',''))); IF v_display NOT IN('','legal','preferred') THEN RAISE EXCEPTION 'Invalid display name mode' USING ERRCODE='22023'; END IF; UPDATE public.players SET full_name=CASE WHEN v_player.verification_status<>'verified' AND v_name IS NOT NULL THEN v_name ELSE full_name END,preferred_name=CASE WHEN p_payload ? 'preferred_name' THEN nullif(trim(p_payload->>'preferred_name'),'') ELSE preferred_name END,bio=CASE WHEN p_payload ? 'bio' THEN nullif(trim(p_payload->>'bio'),'') ELSE bio END,nationality=coalesce(nullif(trim(p_payload->>'nationality'),''),nationality),position=coalesce(v_position,position),preferred_foot=coalesce(case when nullif(p_payload->>'preferred_foot','') is not null then lower(trim(p_payload->>'preferred_foot'))::public.preferred_foot end,preferred_foot),jersey_number=case when p_payload ? 'jersey_number' then nullif(p_payload->>'jersey_number','')::integer else jersey_number end,height_cm=case when p_payload ? 'height_cm' then nullif(p_payload->>'height_cm','')::numeric else height_cm end,weight_kg=case when p_payload ? 'weight_kg' then nullif(p_payload->>'weight_kg','')::numeric else weight_kg end,photo_url=case when p_payload ? 'photo_url' then nullif(trim(p_payload->>'photo_url'),'') else photo_url end,profile_visibility=case when p_payload->>'profile_visibility' in('public','private') then p_payload->>'profile_visibility' else profile_visibility end,display_name_mode=case when v_display<>'' then v_display else display_name_mode end,updated_at=now() WHERE id=v_player.id; RETURN public.get_player_profile(v_player.id); END; $$;
REVOKE ALL ON FUNCTION public.update_my_player_profile(JSONB) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.update_my_player_profile(JSONB) TO authenticated;
CREATE OR REPLACE FUNCTION public.get_player_profile(p_player_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ DECLARE v_player record;v_is_owner boolean;v_is_follower boolean;v_follow_status text;v_attrs jsonb;v_followers bigint;v_display_name text; BEGIN SELECT p.id,p.profile_id,p.full_name,p.preferred_name,p.display_name_mode,p.bio,p.date_of_birth,p.position,p.preferred_foot,p.photo_url,p.club_id,p.jersey_number,p.nationality,p.height_cm,p.weight_kg,p.football_passport_no,p.profile_visibility,p.verification_status,p.verified_at,c.name club_name,c.logo_url club_logo INTO v_player FROM public.players p LEFT JOIN public.clubs c ON c.id=p.club_id WHERE p.id=p_player_id AND p.is_active=true; IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','PLAYER_NOT_FOUND'); END IF; v_is_owner=v_player.profile_id=(SELECT auth.uid()); SELECT pf.status INTO v_follow_status FROM public.player_follows pf WHERE pf.player_id=p_player_id AND pf.follower_profile_id=(SELECT auth.uid()); v_is_follower=v_follow_status='approved'; SELECT count(*) INTO v_followers FROM public.player_follows WHERE player_id=p_player_id AND status='approved'; v_display_name=CASE WHEN v_player.display_name_mode='legal' THEN v_player.full_name ELSE coalesce(v_player.preferred_name,v_player.full_name) END; IF NOT(v_is_owner OR v_player.profile_visibility='public' OR v_is_follower) THEN RETURN jsonb_build_object('ok',true,'restricted',true,'player',jsonb_build_object('id',v_player.id,'preferred_name',v_display_name,'photo_url',v_player.photo_url,'position',v_player.position,'verification_status',v_player.verification_status,'profile_visibility',v_player.profile_visibility,'follower_count',v_followers),'follow_status',coalesce(v_follow_status,'none')); END IF; SELECT to_jsonb(a)-'player_id'-'updated_at' INTO v_attrs FROM public.player_attribute_state a WHERE a.player_id=p_player_id; RETURN jsonb_build_object('ok',true,'restricted',false,'player',jsonb_build_object('id',v_player.id,'full_name',v_player.full_name,'preferred_name',v_display_name,'raw_preferred_name',v_player.preferred_name,'display_name_mode',v_player.display_name_mode,'bio',v_player.bio,'age',extract(year from age(current_date,v_player.date_of_birth))::integer,'position',v_player.position,'preferred_foot',v_player.preferred_foot,'photo_url',v_player.photo_url,'club_id',v_player.club_id,'club_name',v_player.club_name,'club_logo',v_player.club_logo,'jersey_number',v_player.jersey_number,'nationality',v_player.nationality,'height_cm',v_player.height_cm,'weight_kg',v_player.weight_kg,'football_passport_no',v_player.football_passport_no,'verification_status',v_player.verification_status,'verified_at',v_player.verified_at,'profile_visibility',v_player.profile_visibility,'follower_count',v_followers),'attributes',coalesce(v_attrs,'{}'::jsonb),'follow_status',coalesce(v_follow_status,'none')); END; $$;
REVOKE ALL ON FUNCTION public.get_player_profile(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.get_player_profile(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.approve_player_kyc(p_kyc_id uuid,p_reviewer_note text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE v_uid uuid=(SELECT auth.uid());v_k public.identity_verifications%ROWTYPE;v_player public.players%ROWTYPE;v_no bigint;v_prefix text;v_passport text; BEGIN IF v_uid IS NULL OR NOT public.is_league_founder_or_developer() THEN RAISE EXCEPTION 'KYC approval requires PlayPro privileged access' USING ERRCODE='42501'; END IF; SELECT * INTO v_k FROM public.identity_verifications WHERE id=p_kyc_id AND subject_type='player' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'KYC request not found' USING ERRCODE='P0002'; END IF; SELECT * INTO v_player FROM public.players WHERE profile_id=v_k.profile_id AND is_active=true LIMIT 1 FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Player profile not found' USING ERRCODE='P0002'; END IF; IF v_k.status='verified' THEN RETURN jsonb_build_object('ok',true,'status','verified','player_id',v_player.id,'football_passport_no',v_player.football_passport_no); END IF; v_no=nextval('public.playpro_passport_user_no_seq');v_prefix=upper(right(regexp_replace(split_part(trim(v_k.legal_name_claimed),' ',1),'[^A-Za-z]','','g'),4));IF length(v_prefix)<4 THEN v_prefix=upper(rpad(v_prefix,4,'X'));END IF;IF v_k.birth_state_code !~ '^[0-9]{2}$' THEN RAISE EXCEPTION 'Kod negeri kelahiran mesti 2 digit' USING ERRCODE='22023';END IF;v_passport=v_prefix||'-'||v_k.birth_state_code||'-'||lpad(v_no::text,4,'0');UPDATE public.players SET full_name=v_k.legal_name_claimed,verification_status='verified',verified_at=now(),verified_by=v_uid,football_passport_no=v_passport,updated_at=now() WHERE id=v_player.id;UPDATE public.identity_verifications SET status='verified',reviewer_profile_id=v_uid,reviewer_note=p_reviewer_note,reviewed_at=now(),updated_at=now() WHERE id=v_k.id;RETURN jsonb_build_object('ok',true,'status','verified','player_id',v_player.id,'football_passport_no',v_passport,'playpro_user_no',v_no);END; $$;
REVOKE ALL ON FUNCTION public.approve_player_kyc(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.approve_player_kyc(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.get_my_player_kyc_status() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ DECLARE v_uid uuid=(SELECT auth.uid());v_k public.identity_verifications%ROWTYPE;v_p public.players%ROWTYPE;BEGIN SELECT * INTO v_p FROM public.players WHERE profile_id=v_uid AND is_active=true LIMIT 1;IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','PLAYER_NOT_FOUND');END IF;SELECT * INTO v_k FROM public.identity_verifications WHERE profile_id=v_uid AND subject_type='player' ORDER BY created_at DESC LIMIT 1;RETURN jsonb_build_object('ok',true,'verification_status',v_p.verification_status,'football_passport_no',v_p.football_passport_no,'kyc_status',coalesce(v_k.status,'not_submitted'),'kyc_id',v_k.id,'id_type',v_k.id_type,'submitted_at',v_k.submitted_at,'reviewed_at',v_k.reviewed_at,'reviewer_note',v_k.reviewer_note);END; $$;
REVOKE ALL ON FUNCTION public.get_my_player_kyc_status() FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.get_my_player_kyc_status() TO authenticated;
CREATE OR REPLACE FUNCTION public.get_player_card_state(p_player_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ DECLARE v_s record;v_player public.players%ROWTYPE;BEGIN SELECT * INTO v_player FROM public.players WHERE id=p_player_id AND is_active=true;IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','PLAYER_NOT_FOUND');END IF;SELECT s.id,s.matches_remaining,s.matches_suspended,s.matches_served,s.suspension_reason,s.reason_notes,s.start_fixture_id,s.completed_at INTO v_s FROM public.suspensions s WHERE s.player_id=p_player_id AND s.is_active=true AND coalesce(s.matches_remaining,0)>0 ORDER BY s.created_at DESC LIMIT 1;RETURN jsonb_build_object('ok',true,'disciplinary',CASE WHEN v_s.id IS NULL THEN jsonb_build_object('active',false,'state','ACTIVE') ELSE jsonb_build_object('active',true,'state','SUSPENDED','matches_remaining',v_s.matches_remaining,'matches_suspended',v_s.matches_suspended,'matches_served',v_s.matches_served,'reason',v_s.suspension_reason,'notes',v_s.reason_notes,'start_fixture_id',v_s.start_fixture_id) END);END; $$;
REVOKE ALL ON FUNCTION public.get_player_card_state(uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.get_player_card_state(uuid) TO authenticated;
COMMIT;